import{_ as t,o as a,c as o,aa as n}from"./chunks/framework.D7Mdgkg-.js";const u=JSON.parse('{"title":"A Complementary Agent Project","description":"How a separate, user-chosen AI agent could work with Feluqa to create and evolve product software.","frontmatter":{"requestedLanguage":"fr","contentLanguage":"en","languageFallbackNotice":"Cette page n’est pas disponible en Français. La version en anglais est affichée.","sidebarTitle":"Agent Project","icon":"bot","title":"A Complementary Agent Project","description":"How a separate, user-chosen AI agent could work with Feluqa to create and evolve product software.","summary":"Describes a separate, planned agent companion that could let organisations choose a local agent or another supported provider. It outlines how agents could use Feluqa contracts and CLI workflows to create, compile, validate, test, package, and distribute product-specific Modules and Features while respecting privacy, permissions, review, and current implementation limits.","date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","weight":4,"status":"Exploring","tags":["feluqa","agents","complementary-projects","product-direction"],"draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"fr/agents/agentic-development/complementary-agent-project.md","filePath":"fr/agents/agentic-development/complementary-agent-project.md"}'),r={name:"fr/agents/agentic-development/complementary-agent-project.md"};function s(i,e,c,l,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="a-complementary-agent-project" tabindex="-1">A Complementary Agent Project <a class="header-anchor" href="#a-complementary-agent-project" aria-label="Permalink to &quot;A Complementary Agent Project&quot;">​</a></h1><p>Feluqa is intended to work with AI agents, but Feluqa and an agent product are separate projects. Feluqa provides the platform, SDK, extensible Modules and Features, and developer tools. A complementary agent project could help people and organisations use those building blocks to create and evolve their own Products.</p><h2 id="choose-where-the-agent-runs" tabindex="-1">Choose where the agent runs <a class="header-anchor" href="#choose-where-the-agent-runs" aria-label="Permalink to &quot;Choose where the agent runs&quot;">​</a></h2><p>Organisations should be able to use a local agent or choose any other agent they want through an integration the companion supports. A local deployment can keep business requirements, source code, and project data within the organisation&#39;s controlled environment. An organisation that chooses a remote agent decides which provider to use and what information to make available to it. The companion project should make this choice explicit rather than requiring every user to send business-specific context to one external service.</p><h2 id="let-the-agent-work-through-feluqa-s-contracts-and-tools" tabindex="-1">Let the agent work through Feluqa&#39;s contracts and tools <a class="header-anchor" href="#let-the-agent-work-through-feluqa-s-contracts-and-tools" aria-label="Permalink to &quot;Let the agent work through Feluqa&#39;s contracts and tools&quot;">​</a></h2><p>The agent should use Feluqa&#39;s machine-readable project descriptions, module manifests, schemas, capabilities, permissions, and documented extension points. It could then create or change a Module or Feature to meet a product-specific need, while respecting the organisation&#39;s access and approval rules.</p><p>The Feluqa CLI is intended to provide the engineering workflow under the agent: inspect a project, generate or update source, compile it, validate the result, run tests and evaluations, package it, and distribute it through the chosen channel. The workflow should return machine-readable results so the agent and its user can see what succeeded and what needs attention.</p><p>This makes it possible to add a new part to a Product without hand-building every framework layer or enduring a complex deployment process. The agent helps produce software; Feluqa&#39;s contracts, compiler, policy checks, review, and release workflow keep the result within the application&#39;s lifecycle.</p><h2 id="intended-relationship-and-status" tabindex="-1">Intended relationship and status <a class="header-anchor" href="#intended-relationship-and-status" aria-label="Permalink to &quot;Intended relationship and status&quot;">​</a></h2><p>This agent companion is a complementary product direction, not a delivered Feluqa feature. Feluqa does not yet provide the complete agent orchestration, local-agent runtime, provider selection, dynamic extension, compilation-to-distribution workflow, or a named companion product. The <a href="/fr/agents/agentic-development/agent-ready-extensible-modules">agent-ready extensibility concept</a> describes the corresponding Feluqa platform direction.</p>',10)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
